  "about_page_description": "📖 Узнайте больше о Calk.KG - крупнейшей платформе онлайн-калькуляторов для Кыргызстана. Наша миссия, принципы работы, статистика и планы развития. Помогаем 50,000+ пользователям принимать правильные финансовые решения.",
  "about_calc_title": "О проекте",
  "about_calc_subtitle": "Наша миссия — сделать финансовые и повседневные расчеты простыми и доступными для каждого жителя Кыргызстана",
  "about_page_title": "О проекте Calk.KG",
