  "about_our_mission": "Наша миссия",
  "about_mission_text1": "Calk.KG создан для того, чтобы сделать финансовые и повседневные расчеты простыми и доступными для каждого жителя Кыргызстана. Мы верим, что каждый человек должен иметь возможность быстро и точно рассчитать свои финансовые обязательства, планировать бюджет и принимать обоснованные решения.",
