  "about_our_story": "Наша история",
  "about_story_text1": "Проект Calk.KG родился из понимания того, что жителям Кыргызстана нужен простой и надежный инструмент для финансовых расчетов. Слишком часто люди сталкиваются со сложными формулами, устаревшими данными и необходимостью искать информацию по множеству источников.",
  "about_story_text2": "Мы решили создать единую платформу, где каждый может быстро получить точный расчет — будь то ипотека, налоги, коммунальные платежи или социальные пособия. Все калькуляторы адаптированы специально под законодательство и особенности Кыргызстана.",
  "about_story_text3": "Сегодня Calk.KG — это не просто набор калькуляторов, а надежный помощник в принятии финансовых решений для тысяч семей по всей стране.",
