  "mortgage_better_offer_legend": "Более выгодное предложение",
  "mortgage_worse_offer_legend": "Менее выгодное предложение",
  "mortgage_bank_rates_notice": "Ставки и условия банков являются ориентировочными и могут изменяться. Для получения актуальной информации обратитесь в выбранный банк.",
  "mortgage_popular_scenarios": "Популярные сценарии ипотеки:",
  "mortgage_per_month_short": "сом/мес",
  "mortgage_down_payment_short": "первонач. взнос:",
  "mortgage_overpayment_short": "переплата:",
  "mortgage_what_is_content": "это долгосрочный кредит на покупку недвижимости (квартиры, дома, земельного участка), при котором приобретаемое жилье становится залогом по кредиту. Это означает, что до полного погашения долга недвижимость находится в залоге у банка.",
  "mortgage_what_is_kr_context": "В Кыргызстане ипотека является основным инструментом для приобретения собственного жилья. Средняя стоимость квартиры в Бишкеке составляет 3-8 млн сомов, что делает невозможным покупку за наличные для большинства граждан.",
  "mortgage_how_works_title": "Принцип работы:",
  "mortgage_how_works_content": "Вы вносите первоначальный взнос (10-30% стоимости), банк выдает оставшуюся сумму, и вы становитесь владельцем жилья с обременением. После полного погашения кредита обременение снимается.",
  "mortgage_type_new_building": "Ипотека на первичное жилье",
  "mortgage_type_new_building_desc": "Покупка квартиры в новостройке напрямую у застройщика. Обычно более выгодные условия, но требует времени на сдачу объекта.",
  "mortgage_type_new_rate": "Ставка: 14-17% годовых",
  "mortgage_type_new_term": "Срок: до 25 лет",
  "mortgage_type_new_down": "Первый взнос: от 10%",
  "mortgage_type_secondary": "Ипотека на вторичное жилье",
  "mortgage_type_secondary_desc": "Приобретение квартиры или дома на вторичном рынке. Можно заселиться сразу, но ставки могут быть выше.",
  "mortgage_type_secondary_rate": "Ставка: 15-19% годовых",
  "mortgage_type_secondary_term": "Срок: до 20 лет",
  "mortgage_type_secondary_down": "Первый взнос: от 20%",
  "mortgage_type_construction": "Ипотека на строительство",
  "mortgage_type_construction_desc": "Кредит на строительство частного дома. Средства выдаются поэтапно по мере выполнения работ.",
  "mortgage_type_construction_rate": "Ставка: 16-20% годовых",
  "mortgage_type_construction_term": "Срок: до 15 лет",
  "mortgage_type_construction_down": "Первый взнос: от 30%",
  "mortgage_type_government": "Государственная ипотека",
  "mortgage_type_government_desc": "Льготные программы для определенных категорий граждан (молодые семьи, бюджетники, военнослужащие).",
  "mortgage_type_government_rate": "Ставка: 10-12% годовых",
  "mortgage_type_government_term": "Срок: до 20 лет",
  "mortgage_type_government_down": "Первый взнос: от 10%",
  "mortgage_choose_step1_title": "Оцените свои финансовые возможности",
  "mortgage_choose_step1_content": "Рассчитайте максимальный ежемесячный платеж (не более 40% от дохода семьи). Учитывайте дополнительные расходы: страхование, оценка, нотариус (≈2-3% от суммы кредита).",
  "mortgage_choose_step2_title": "Накопите первоначальный взнос",
  "mortgage_choose_step2_content": "Чем больше первоначальный взнос, тем выгоднее условия. Минимум — 10%, оптимально — 20-30%. При взносе более 30% некоторые банки снижают ставку на 0.5-1%.",
  "mortgage_choose_step3_title": "Сравните предложения банков",
  "mortgage_choose_step3_content": "Не смотрите только на процентную ставку. Сравните полную стоимость кредита (ПСК), которая включает все комиссии и платежи. Используйте наш калькулятор для сравнения.",
  "mortgage_choose_step4_title": "Выберите оптимальный срок",
  "mortgage_choose_step4_content": "Короткий срок (5-10 лет) = большой платеж, но меньше переплата.\nДлинный срок (20-25 лет) = маленький платеж, но больше переплата.\nЗолотая середина — 15 лет.",
  "mortgage_choose_step5_title": "Проверьте скрытые расходы",
  "mortgage_choose_step5_content": "Уточните: есть ли комиссия за выдачу, за ведение счета, за досрочное погашение, обязательно ли страхование жизни. Эти расходы могут добавить 1-2% к ставке.",
  "mortgage_choose_step6_title": "Соберите документы заранее",
  "mortgage_choose_step6_content": "Типовой пакет: паспорт, справка 2-НДФЛ (или о доходах), трудовая книжка, документы на недвижимость, справка о семейном положении. Подготовка займет 2-4 недели.",
  "mortgage_requirements_title": "Требования к заемщику в КР",
  "mortgage_requirements_general": "Общие требования:",
  "mortgage_requirements_general_1": "Гражданство КР или ВНЖ",
  "mortgage_requirements_general_2": "Возраст: от 21 до 65 лет",
  "mortgage_requirements_general_3": "Официальный доход минимум 6 месяцев",
  "mortgage_requirements_general_4": "Трудовой стаж: от 1 года (общий), от 6 мес (последнее место)",
  "mortgage_requirements_general_5": "Положительная кредитная история",
  "mortgage_requirements_additional": "Дополнительные условия:",
  "mortgage_requirements_additional_1": "Минимальный доход: 25,000-40,000 сом/мес",
  "mortgage_requirements_additional_2": "Платежеспособность: платеж ≤ 40-50% дохода",
