  "mortgage_documents_title": "Необходимые документы для ипотеки",
  "mortgage_documents_borrower": "📄 Документы заемщика:",
  "mortgage_documents_borrower_1": "Паспорт гражданина КР",
  "mortgage_documents_borrower_2": "ИНН (идентификационный номер)",
  "mortgage_documents_borrower_3": "Справка о доходах (2-НДФЛ или по форме банка) за 6-12 месяцев",
  "mortgage_documents_borrower_4": "Трудовая книжка (копия, заверенная работодателем)",
  "mortgage_documents_borrower_5": "Справка с места работы",
