  "passport_guide_title": "Полное руководство по получению ID-карты и загранпаспорта в КР 2026",
  "passport_guide_intro": "В Кыргызстане получение ID-карты и загранпаспорта - стандартная процедура с фиксированной госпошлиной, которая варьируется в зависимости от выбранного срока оформления. Наш калькулятор поможет рассчитать точную стоимость.",
  "passport_faq_q1": "Когда нужно получать ID-карту?",
  "passport_faq_a1": "ID-карта обязательна с 16 лет. Срок действия - 10 лет. После истечения срока необходимо получить новую.",
  "passport_faq_q2": "Какие документы нужны для загранпаспорта?",
  "passport_faq_a2": "ID-карта, фото 3х4 (2 шт.), заявление. Для детей - свидетельство о рождении и ID-карта родителя.",
  "passport_faq_q3": "Можно ли получить быстрее?",
  "passport_faq_a3": "Да, есть ускоренное оформление за дополнительную плату: 8 дней, 4 дня или 2 дня. Госпошлина увеличивается в зависимости от скорости.",
  "passport_tip_1": "Приходите с утра в будние дни - меньше очередь",
