  "single_tax_guide_title": "Единый налог для ИП в Кыргызстане: полное руководство 2026",
  "single_tax_what_is_title": "Что такое единый налог?",
  "single_tax_what_is_text": "Единый налог — это специальный налоговый режим для индивидуальных предпринимателей в Кыргызстане, который заменяет несколько налогов одним платежом. Вместо того чтобы платить подоходный налог, НДС и налог на имущество отдельно, ИП платит только один фиксированный процент от выручки.",
  "single_tax_who_can_title": "Кто может применять единый налог?",
  "single_tax_who_can_text": "Право на применение единого налога имеют индивидуальные предприниматели, годовая выручка которых не превышает 8 млн сомов. Это около 1 млн сомов в месяц. Данный режим подходит для малого бизнеса и начинающих предпринимателей.",
  "single_tax_requirements_title": "Требования для применения:",
  "single_tax_req_1": "Регистрация в качестве индивидуального предпринимателя",
  "single_tax_req_2": "Годовая выручка не более 8 млн сомов",
