  "single_tax_comparison_title": "Сравнение с другими режимами",
  "single_tax_vs_general": "Единый налог vs Общий режим",
  "single_tax_vs_general_text": "На общем режиме вы платите 10% подоходного налога с чистой прибыли плюс НДС 12%. Единый налог проще, но берется с выручки. Если у вас большие расходы (более 40-60% от выручки), общий режим может быть выгоднее.",
  "single_tax_vs_patent": "Единый налог vs Патент",
  "single_tax_vs_patent_text": "Патентная система — это фиксированный платеж независимо от выручки. Патент выгоден при больших оборотах, но есть ограничения по видам деятельности. Единый налог более гибкий.",
  "single_tax_how_to_pay_title": "Как платить единый налог?",
  "single_tax_how_to_pay_text": "Налог платится ежемесячно до 20 числа следующего месяца. Декларация подается ежеквартально до 20 числа месяца, следующего за кварталом. Платить можно через банк, мобильные приложения или сайт налоговой службы.",
  "single_tax_payment_methods": "Способы оплаты:",
  "single_tax_payment_1": "Через банк по квитанции",
  "single_tax_payment_2": "Мобильное приложение O! Денька, MegaPay и др.",
  "single_tax_payment_3": "Личный кабинет налогоплательщика на salyk.kg",
  "single_tax_payment_4": "Через терминалы оплаты",
  "single_tax_examples_title": "Примеры расчета единого налога",
  "single_tax_example_1_title": "Пример 1: Розничная торговля",
  "single_tax_example_1_text": "Вы продаете одежду. Месячная выручка — 200 000 сом. Ставка для торговли — 4%. Единый налог: 200 000 × 4% = 8 000 сом в месяц.",
  "single_tax_example_2_title": "Пример 2: Услуги",
  "single_tax_example_2_text": "Вы парикмахер. Месячная выручка — 150 000 сом. Ставка для услуг — 6%. Единый налог: 150 000 × 6% = 9 000 сом в месяц.",
  "single_tax_example_3_title": "Пример 3: Общепит",
  "single_tax_example_3_text": "У вас небольшое кафе. Месячная выручка — 400 000 сом. Ставка — 6%. Единый налог: 400 000 × 6% = 24 000 сом в месяц.",
  "single_tax_faq_title": "Часто задаваемые вопросы",
  "single_tax_faq_q1": "Можно ли совмещать виды деятельности?",
  "single_tax_faq_a1": "Да, можно. Но для каждого вида деятельности применяется своя ставка. Например, если вы продаете товары (4%) и оказываете услуги (6%), нужно вести раздельный учет выручки.",
  "single_tax_faq_q2": "Что делать, если выручка превысила 8 млн?",
  "single_tax_faq_a2": "Если годовая выручка превысила 8 млн сом, вы обязаны в течение 10 дней перейти на общий режим налогообложения. С месяца превышения начинают действовать стандартные налоговые ставки.",
  "single_tax_faq_q3": "Нужно ли платить соцвзносы?",
  "single_tax_faq_a3": "Да, единый налог не отменяет обязательные взносы в Социальный фонд. ИП на едином налоге платят фиксированный взнос — около 1 800 сом в месяц (10% от минимальной зарплаты).",
  "single_tax_faq_q4": "Можно ли нанимать работников?",
  "single_tax_faq_a4": "Да, можно нанимать до 10 работников. За каждого работника нужно платить подоходный налог (10%) и социальные взносы (27.25%) с их зарплаты.",
  "single_tax_faq_q5": "Как перейти на единый налог?",
  "single_tax_faq_a5": "При регистрации ИП можно сразу выбрать единый налог. Если вы уже работаете на другом режиме, подайте заявление в налоговую инспекцию. Переход возможен с начала следующего квартала.",
  "single_tax_tips_title": "Полезные советы для ИП",
  "single_tax_tip_1": "Ведите учет выручки ежедневно, даже если не требуется касса",
  "single_tax_tip_2": "Сохраняйте все чеки и накладные на закупку товаров",
  "single_tax_tip_3": "Платите налог вовремя — пени составляют 0.05% в день",
  "single_tax_tip_4": "Следите за лимитом выручки, чтобы не пропустить переход",
  "single_tax_tip_5": "Проверяйте изменения в Налоговом кодексе — ставки могут меняться",
