  "property_faq_title": "Часто задаваемые вопросы",
  "property_guide_title": "Полное руководство по налогу на недвижимость в Кыргызстане 2026",
  "property_guide_intro": "Налог на недвижимость — это ежегодный платеж за владение жилой недвижимостью в Кыргызстане. Закон предусматривает льготную площадь, с которой налог не взимается: 80 м² для квартир и 150 м² для домов. Наш калькулятор поможет точно рассчитать сумму налога с учетом всех льгот.",
  "property_guide_law_title": "Законодательная база 2026",
  "property_guide_law_text": "Налог на недвижимость регулируется Налоговым кодексом КР (статьи 339-345). С января 2026 года действуют обновленные правила: максимальная ставка — 100 сом/м², срок уплаты — до 1 сентября, льготная площадь сохранена (80 м² для квартир, 150 м² для домов).",
  "property_guide_rates_title": "Ставки налога по регионам 2026",
  "property_rate_bishkek": "Бишкек: 25-40 сом/м² (зависит от района)",
  "property_rate_osh": "Ош: 15-25 сом/м²",
  "property_rate_jalal": "Джалал-Абад: 12-20 сом/м²",
  "property_rate_karakol": "Каракол: 15-22 сом/м²",
  "property_rate_other": "Другие города: 8-18 сом/м²",
  "property_rate_note": "Точные ставки устанавливаются местными кенешами и могут меняться ежегодно",
  "property_guide_benefits_title": "Льготы и налоговые вычеты",
  "property_benefit_1": "Квартира: первые 80 м² не облагаются налогом",
  "property_benefit_2": "Жилой дом: первые 150 м² не облагаются налогом",
  "property_benefit_3": "Ветераны ВОВ и инвалиды 1-2 группы: полное освобождение",
  "property_benefit_4": "Многодетные семьи (5+ детей): освобождение на один объект",
  "property_benefit_5": "Пенсионеры: льгот нет, платят на общих основаниях",
  "property_guide_calc_title": "Как рассчитывается налог",
  "property_calc_step1": "1. Определяем общую площадь по техпаспорту (например, 120 м²)",
  "property_calc_step2": "2. Вычитаем льготную площадь (для квартиры 80 м²)",
  "property_calc_step3": "3. Получаем налогооблагаемую площадь (120 - 80 = 40 м²)",
  "property_calc_step4": "4. Умножаем на ставку (например, 30 сом/м²)",
  "property_calc_step5": "5. Итоговый налог: 40 × 30 = 1,200 сом/год",
  "property_faq_q1": "До какого числа нужно заплатить налог?",
  "property_faq_a1": "Налог на недвижимость за текущий год необходимо оплатить до 1 сентября. Например, за 2026 год нужно заплатить до 1 сентября 2026 года. При просрочке начисляется пеня 0.7% от суммы долга за каждый день.",
  "property_faq_q2": "Нужно ли платить налог на новую квартиру?",
  "property_faq_a2": "Да, налог начинает начисляться с момента регистрации права собственности в Госрегистре. Если вы зарегистрировали квартиру в середине года, налог будет рассчитан пропорционально количеству месяцев владения.",
  "property_faq_q3": "Платят ли пенсионеры налог на недвижимость?",
  "property_faq_a3": "Да, пенсионеры платят налог на общих основаниях. Льготы предоставляются только ветеранам ВОВ, инвалидам 1-2 группы и многодетным семьям (5+ детей). Пенсионный возраст не является основанием для освобождения от налога.",
  "property_faq_q4": "Что делать, если не пришла квитанция?",
  "property_faq_a4": "Отсутствие квитанции не освобождает от уплаты налога. Проверьте задолженность в личном кабинете на сайте ГНС КР (cabinet.salyk.kg) или обратитесь в территориальное подразделение ГНС. Можно также оплатить через мобильные приложения банков по ИНН.",
  "property_faq_q5": "Облагается ли налогом дача или гараж?",
  "property_faq_a5": "Жилые дома на дачных участках облагаются налогом на общих основаниях с льготой 150 м². Гаражи как нежилые помещения облагаются налогом на другое имущество по ставкам местных кенешей (обычно 5-15 сом/м²).",
  "property_faq_q6": "Можно ли получить льготу на несколько объектов?",
  "property_faq_a6": "Нет, налоговая льгота (80 м² или 150 м²) применяется к каждому объекту отдельно. Если у вас квартира 120 м² и дом 200 м², то квартира: (120-80)×ставка, дом: (200-150)×ставка. Льготы суммируются для каждого объекта.",
  "property_tips_title": "Практические советы",
  "property_tip_1": "Проверяйте начисления в личном кабинете ГНС КР ежегодно до 1 августа",
  "property_tip_2": "Оплачивайте налог до конца августа, чтобы избежать очередей",
  "property_tip_3": "Храните квитанции об оплате минимум 3 года",
  "property_tip_4": "При продаже недвижимости проверьте отсутствие задолженности — иначе сделка может не пройти",
  "property_tip_5": "Если площадь в техпаспорте указана неверно, обратитесь в БТИ для исправления",
  "property_tip_6": "Налог можно оплатить в банках, через терминалы, мобильные приложения и на сайте ГНС",
  "property_mistakes_title": "Распространенные ошибки",
  "property_mistake_1": "Неоплата налога из-за неполучения квитанции — вы обязаны платить независимо",
  "property_mistake_2": "Ожидание льгот для пенсионеров — их нет",
  "property_mistake_3": "Игнорирование пени при просрочке — может вырасти до 50% от суммы налога",
  "property_mistake_4": "Неуказание всех объектов недвижимости в декларации — штраф 5,000-10,000 сом",
  "property_mistake_5": "Расчет налога без учета льготной площади — переплата",
