  "water_economy_40_60": "Экономия до 40-60%!",
  "water_no_meter_calc": "При отсутствии счетчика расчет ведется по нормативу: 6-8 м³ на человека в месяц. Фактическое потребление обычно в 2-3 раза меньше, что делает счетчик очень выгодным.",
