  "water_total_savings_text": "Общая экономия:",
  "water_total_savings_desc": "Применяя все методы, средняя семья может сократить расход воды на 30-40%, что составляет 50-100 сомов в месяц или 600-1200 сомов в год!",
  "water_faq_broken_meter": "Что делать, если счетчик неисправен?",
  "water_faq_broken_meter_a": "Сообщите в водоканал в течение 3 дней. До замены счетчика расчет будет вестись по среднему потреблению за последние 6 месяцев. Замена счетчика производится за счет владельца жилья. Стоимость: 2000-4000 сом (счетчик + установка + опломбировка).",
  "water_faq_verification": "Как часто нужно поверять счетчик?",
  "water_faq_verification_a": "Холодная вода: каждые 6 лет. Горячая вода: каждые 4 года. Дата следующей поверки указана в паспорте счетчика. Поверку проводят аккредитованные организации. Стоимость: 500-1000 сом. Без своевременной поверки счетчик считается неисправным.",
  "water_faq_benefits": "Можно ли получить льготы на воду?",
  "water_faq_benefits_a": "Да, льготы предоставляются: ветеранам ВОВ и труда (50% скидка), инвалидам 1-2 группы (30-50%), многодетным семьям (в некоторых регионах). Для получения льготы обратитесь в отдел соцзащиты по месту жительства со справками, затем в водоканал.",
  "water_faq_disconnect": "Могут ли отключить воду за неуплату?",
  "water_faq_disconnect_a": "Да, при задолженности за 2-3 месяца. Перед отключением направляется письменное уведомление за 10 дней. Исключения: семьи с детьми до 3 лет, инвалидами 1 группы, в период карантина. Для возобновления подачи погасите долг и оплатите повторное подключение (обычно 200-500 сом).",
  "water_faq_quality": "Почему вода мутная или с запахом?",
  "water_faq_quality_a": "Причины: профилактика/ремонт водопровода (временно), старые трубы в доме (ржавчина), повышенное содержание хлора (обеззараживание). Решения: установите фильтры, дайте воде отстояться 2-3 часа, обратитесь в водоканал для проверки качества. Экстренная линия водоканала: 150 (Бишкек).",
  "water_faq_average_consumption": "Сколько воды потребляет средняя семья?",
  "water_faq_average_a1": "Среднее потребление на человека: 3-5 м³/месяц",
  "water_faq_average_a2": "1 человек: 3-5 м³ (42-70 сом)",
