  "pension_npf_check_text": "Зарегистрируйтесь на сайте вашего НПФ или в мобильном приложении. Там вы увидите: сумму накоплений, ежемесячные взносы, историю доходности.",
  "pension_faq_withdraw": "Можно ли снять пенсионные накопления досрочно?",
  "pension_faq_withdraw_answer": "Нет, досрочное снятие накопительной части невозможно. Исключения: 1) Переезд на ПМЖ за границу (можно снять всю сумму). 2) Инвалидность 1-2 группы (досрочная пенсия). 3) В случае смерти",
  "pension_faq_unofficial": "Что будет, если я работал неофициально?",
  "pension_faq_unofficial_answer": "Без официального трудоустройства работодатель не делает отчисления в НПФ и Соцфонд. Это значит: 1) Накопительная часть не формируется. 2) Стаж не идет. 3) В будущем получите только минимальную базовую пенсию (3500-4000 сом). Рекомендация: требуйте официального оформления или регистрируйтесь как ИП и платите взносы самостоятельно.",
  "pension_faq_voluntary": "Можно ли делать добровольные взносы в НПФ?",
  "pension_faq_voluntary_answer": "Да! Любой гражданин может делать добровольные взносы в НПФ, чтобы увеличить будущую пенсию. Минимальный взнос: от 500 сом. Преимущества: 1) Увеличите накопительную часть. 2) Взносы инвестируются НПФ (доходность 7-9% годовых). 3) Налоговый вычет 10% от суммы взноса (можно вернуть подоходный налог). Оформить можно в любом НПФ или онлайн.",
  "pension_faq_entrepreneur": "Как платят взносы ИП и патентники?",
  "pension_faq_entrepreneur_answer": "ИП платит фиксированные взносы в Соцфонд независимо от дохода: в 2026 году ~1200 сом/мес (14,400 сом/год). Из них часть идет на формирование пенсии. По патенту: взносы включены в стоимость патента. Чтобы увеличить будущую пенсию, делайте добровольные взносы в НПФ (минимум 500 сом/мес).",
  "pension_faq_solidarity": "Что такое солидарный компонент?",
  "pension_faq_solidarity_answer": "Солидарный компонент - это часть взносов работодателя (17,25%), которая идет в общий \"котел\" Соцфонда и распределяется на выплату текущих пенсий, пособий, больничных. Эти деньги НЕ накапливаются на вашем личном счете. Ваши личные накопления формируются только из 10%, которые работодатель перечисляет в НПФ. Именно эти 10% находятся на вашем",
  "pension_faq_solidarity_answer_2": "индивидуальном счете в НПФ.",
  "pension_faq_apply": "Как оформить пенсию?",
  "pension_faq_apply_timeline": "За 6 месяцев до пенсионного возраста:",
  "pension_faq_apply_step1": "Соберите документы: паспорт, трудовая книжка, справки о зарплате",
  "pension_faq_apply_step2": "Обратитесь в Социальный фонд по месту жительства",
  "pension_faq_apply_step3": "Подайте заявление (можно онлайн через портал sfkr.kg)",
  "pension_faq_apply_step4": "Дождитесь решения (30 дней)",
  "pension_faq_apply_step5": "Укажите способ получения: на карту, почтой, через банк",
  "pension_faq_apply_phone": "Телефон горячей линии Соцфонда:",
  "pension_faq_apply_phone_number": "150 (бесплатно)",
  "pension_increase_tip1": "1. Работайте официально с \"белой\" зарплатой",
  "pension_increase_tip1_desc": "Разница в пенсии: 4000 сом (без стажа) vs 20,000+ сом (с накоплениями).",
  "pension_increase_tip2": "2. Делайте добровольные взносы",
  "pension_increase_tip2_desc": "Даже 2000-3000 сом/мес дополнительно за 20-30 лет превратятся в существенную прибавку к пенсии (15,000-30,000 сом/мес дополнительно).",
  "pension_increase_tip3": "3. Выбирайте НПФ с высокой доходностью",
  "pension_increase_tip3_desc": "Разница в доходности 1-2% годовых за 30 лет может дать разницу в сотни тысяч сомов. Сравнивайте доходность НПФ ежегодно на сайте Социального фонда.",
  "pension_increase_tip4": "4. Следите за своими отчислениями",
  "pension_increase_tip4_desc": "Проверяйте поступления взносов минимум раз в год через личный кабинет НПФ. Ошибки работодателя могут стоить вам десятков тысяч сомов.",
