  "family_guide_intro": "Государственное пособие \"үй-бүлөгө көмөк\" предоставляется малоимущим семьям с детьми до 16 лет. Размер зависит от количества детей и дохода семьи.",
  "family_faq_q1": "Какой порог дохода для получения пособия?",
  "family_faq_a1": "В 2026 году порог - 2,800 сом на человека в месяц. Если средний доход на члена семьи ниже этой суммы, семья имеет право на пособие.",
