  "effective_rate_tooltip": "Процент переплаты от суммы кредита",
  "salary_calc_description": "💰 Точный расчет зарплаты \"на руки\" в Кыргызстане! Рассчитайте подоходный налог (10% или 5% для ПВТ) и отчисления в Соцфонд (10%). Быстро, бесплатно, с детализацией всех вычетов.",
  "loan_calc_description": "💳 Калькулятор потребительских кредитов в Кыргызстане! Рассчитайте ежемесячный платеж, переплату и сравните предложения всех банков КР. Айыл Банк, Дос-Кредобанк, ФКУР и другие.",
  "gas_calc_description": "🔥 Рассчитайте стоимость природного газа в Кыргызстане! Тарифы для населения, отопления, коммерческих и промышленных потребителей. Сезонные коэффициенты зима/лето.",
  "electricity_calc_description": "⚡ Рассчитайте плату за электроэнергию в Кыргызстане! Льготные тарифы для высокогорных районов и малообеспеченных семей. Актуальные ставки и лимиты потребления.",
