  "taxitax_calc_title": "Налог для таксистов и курьеров КР 2026 — калькулятор 1%",
  "taxi_tax_calc_description": "🚕 Налог для таксистов и курьеров через агрегаторы в КР! Ставка 1% от дохода. Namba Taxi, Yandex, InDriver, Glovo. Простой расчет подоходного налога для самозанятых.",
  "taxitax_calc_description": "🚕 Налог для таксистов и курьеров через агрегаторы в КР! Ставка 1% от дохода. Namba Taxi, Yandex, InDriver, Glovo. Простой расчет подоходного налога для самозанятых.",
  "zakat_calc_description": "☪️ Рассчитайте закят по исламским принципам! Нисаб 85 г золота, ставка 2.5% с накоплений. Калькулятор религиозного пожертвования для мусульман Кыргызстана.",
  "wedding_calc_description": "💒 Спланируйте бюджет тоя/свадьбы в Кыргызстане! Расчет затрат: банкет, тамада, декор, фото/видео, кыз узатуу. Полная калькуляция для традиционного киргизского торжества.",
  "salary_calc_keywords": "зарплата, калькулятор, подоходный налог, соцфонд, Кыргызстан, зарплата на руки",
  "salary_info_title": "Как рассчитывается зарплата в Кыргызстане",
  "salary_info_text_1": "Расчет заработной платы в Кыргызстане регулируется Налоговым кодексом КР и Законом о Социальном фонде. При начислении зарплаты работодатель обязан удержать налоги и социальные отчисления.",
  "salary_info_text_2": "Формула расчета чистой зарплаты: Чистая зарплата = Гросс - Соцфонд (10%) - Подоходный налог (10% или 5%). Сначала вычитается взнос в Социальный фонд, затем от оставшейся суммы рассчитывается подоходный налог.",
  "salary_info_text_3": "Для резидентов Парка высоких технологий (ПВТ) действует льготная ставка подоходного налога 5% вместо стандартных 10%. Это существенная экономия для IT-специалистов и сотрудников технологических компаний.",
  "salary_deductions_title": "Обязательные отчисления с зарплаты",
  "salary_deductions_list": [
    "Социальный фонд (Соцфонд) — 10% от начисленной зарплаты",
    "Подоходный налог — 10% от суммы после вычета Соцфонда (5% для ПВТ)",
    "Итого удержания: примерно 19% от гросс-зарплаты (14.5% для ПВТ)"
  ],
  "salary_example_title": "Пример расчета",
  "salary_example_text": "При зарплате 50,000 сом (гросс): Соцфонд = 5,000 сом, налоговая база = 45,000 сом, подоходный налог = 4,500 сом. Итого на руки: 40,500 сом.",
  "salary_faq_1_q": "Кто платит взносы в Соцфонд?",
  "salary_faq_1_a": "Работник уплачивает 10% от зарплаты, работодатель дополнительно 17.25% (не удерживается из зарплаты работника).",
  "salary_faq_2_q": "Как получить льготную ставку 5%?",
  "salary_faq_2_a": "Льготная ставка доступна только для сотрудников компаний-резидентов Парка высоких технологий (ПВТ).",
  "salary_faq_3_q": "Есть ли налоговые вычеты?",
