  "auto_loan_calculate_load_desc": "Ежемесячный платеж не должен превышать 40% вашего дохода. Учитывайте также расходы на бензин, страховку, ремонт и обслуживание.",
  "auto_loan_choose_term_title": "3. Выбирайте оптимальный срок",
  "auto_loan_choose_term_desc": "Короткий срок = меньше переплата, но выше ежемесячный платеж. Длинный срок = ниже платеж, но больше переплата по процентам.",
  "auto_loan_hidden_fees_title": "Скрытые комиссии:",
  "auto_loan_hidden_fees_desc": "Уточните все дополнительные расходы (оценка авто, оформление, страховка)",
  "auto_loan_early_repayment_title": "Досрочное погашение:",
  "auto_loan_early_repayment_desc": "Проверьте условия досрочного погашения – некоторые банки берут штраф",
  "auto_loan_insurance_title": "Страхование:",
  "auto_loan_insurance_desc": "КАСКО обычно обязательно. Сравните стоимость в разных страховых",
  "auto_loan_vehicle_condition_title": "Состояние авто:",
  "auto_loan_vehicle_condition_desc": "Для б/у авто часто выше ставка и короче срок",
  "auto_loan_repay_early_tip": "Гасите кредит досрочно при первой возможности – это существенно снизит переплату",
  "auto_loan_compare_offers_title": "Сравните предложения",
  "auto_loan_compare_offers_desc": "Обойдите несколько банков или используйте онлайн-калькуляторы для сравнения",
  "auto_loan_improve_credit_title": "Улучшите кредитную историю",
  "auto_loan_improve_credit_desc": "Хорошая кредитная история может снизить ставку на 2-5%",
  "auto_loan_increase_down_payment_title": "Увеличьте первый взнос",
  "auto_loan_increase_down_payment_desc": "Чем больше первоначальный взнос, тем меньше сумма кредита и переплата",
  "auto_loan_early_repayment_tip_title": "Досрочное погашение",
  "auto_loan_improve_credit_desc_alt": "Хорошая кредитная история может дать вам скидку на процентную ставку",
  "auto_loan_faq_q1": "Можно ли взять автокредит без первоначального взноса?",
  "auto_loan_faq_a1": "Да, некоторые банки предлагают автокредиты без первоначального взноса, но процентная ставка будет выше (обычно на 3-5%). Также могут потребоваться дополнительные гарантии или поручители.",
  "auto_loan_faq_q2": "Что лучше – автокредит или потребительский кредит?",
  "auto_loan_faq_a2": "Автокредит обычно выгоднее из-за более низкой ставки. Но есть минус – автомобиль в залоге. Если вы не хотите, чтобы машина была в залоге, можно взять потребительский кредит, но переплата будет больше.",
  "auto_loan_faq_q3": "Можно ли досрочно погасить автокредит?",
  "auto_loan_faq_a3": "Да, большинство банков КР разрешают досрочное погашение без штрафов. Но обязательно уточните этот момент в договоре – у некоторых банков могут быть ограничения.",
  "auto_loan_faq_q4": "Нужна ли страховка КАСКО для автокредита?",
  "auto_loan_faq_a4": "Да, практически все банки требуют КАСКО на весь срок кредита. Стоимость страховки обычно 3-7% от стоимости автомобиля в год. Учитывайте этот расход при расчете бюджета.",
  "auto_loan_faq_q5": "На какой срок лучше брать автокредит?",
  "auto_loan_faq_a5": "Оптимально 2-3 года (24-36 месяцев). Это баланс между комфортным ежемесячным платежом и разумной переплатой. На 5 лет брать невыгодно – переплата будет очень большой, плюс автомобиль за это время сильно теряет в цене.",
  "auto_loan_disclaimer_title": "Важно:",
  "auto_loan_disclaimer_text": "Данный калькулятор дает ориентировочные расчеты. Для получения точной информации по условиям автокредитования обратитесь непосредственно в банк. Ставки и условия могут меняться.",
  "patent_tax_regime_choice": "Выбор налогового режима:",
  "patent_compare_with_single_tax": "Сравните патент с единым налогом для ИП или новым льготным режимом для таксистов (1%).",
