  "zakat_religious_notice_title": "🕌 РЕЛИГИОЗНОЕ УВЕДОМЛЕНИЕ",
  "zakat_religious_notice_text1": "<strong>Данный калькулятор является вспомогательным инструментом</strong> для предварительного расчета закята. Он основан на общепринятых исламских принципах и может не учитывать все индивидуальные обстоятельства.",
  "zakat_religious_notice_text2": "Закят — это <strong>религиозная обязанность мусульманина</strong>, установленная Аллахом. Для получения <strong>точных религиозных наставлений</strong> и разъяснений сложных случаев обратитесь к <strong>квалифицированным религиозным ученым</strong>.",
  "zakat_religious_notice_text3": "<strong>Контакты в КР:</strong> Духовное управление мусульман Кыргызской Республики или ваша местная мечеть.",
  "zakat_faq_title": "Часто задаваемые вопросы",
  "zakat_guide_title": "Полное руководство по закяту в Кыргызстане 2026",
  "zakat_guide_intro": "Закят - обязательное пожертвование (2.5% от чистых активов), один из пяти столпов ислама. Выплачивается ежегодно при достижении нисаба (порога богатства).",
  "zakat_faq_q1": "Что такое нисаб?",
  "zakat_faq_a1": "Нисаб - минимальный порог богатства, при котором обязателен закят. В 2026 году эквивалент 85 г золота или 595 г серебра. В сомах примерно 250,000-300,000 сом.",
  "zakat_faq_q2": "С каких активов платится закят?",
  "zakat_faq_a2": "Деньги, золото, серебро, торговые товары, акции, сельхоз продукция. НЕ платится с личного жилья, автомобиля для семьи, рабочих инструментов.",
  "zakat_faq_q3": "Как рассчитать закят?",
  "zakat_faq_a3": "Сложите все активы (наличные + вклады + золото + товары), вычтите долги. Если сумма > нисаба, выплатите 2.5% от чистых активов.",
  "zakat_faq_q4": "Куда передавать закят?",
  "zakat_faq_a4": "Нуждающимся мусульманам, сиротам, должникам, путникам, на пути Аллаха. В КР можно через ДУМК, мечети или напрямую нуждающимся.",
  "zakat_tip_1": "Закят выплачивается раз в год (лунный год 354 дня)",
  "zakat_tip_2": "Лучшее время - Рамадан, но можно в любой месяц",
  "zakat_tip_3": "Посоветуйтесь с имамом при сложных случаях",
