  "alimony_faq_title": "Часто задаваемые вопросы",
  "alimony_guide_title": "Полное руководство по алиментам в Кыргызстане 2026",
  "alimony_guide_intro": "Алименты - обязательные выплаты на содержание детей согласно Семейному кодексу КР. Размер зависит от дохода родителя и количества детей: 25% на одного, 33% на двоих, 50% на троих и более.",
  "alimony_faq_q1": "Как подать на алименты?",
  "alimony_faq_a1": "Подайте заявление в суд по месту жительства ребенка или ответчика. Документы: свидетельство о рождении, справка о доходах, св-во о браке/разводе. Госпошлина не взимается.",
  "alimony_faq_q2": "Что если отец безработный?",
  "alimony_faq_a2": "Алименты рассчитываются от средней зарплаты по региону проживания. В 2026 году по Кыргызстану - около 25,000-30,000 сом.",
  "alimony_faq_q3": "Можно ли изменить размер?",
  "alimony_faq_a3": "Да, через суд при изменении обстоятельств (рост/падение дохода, появление других иждивенцев, болезнь ребенка и т.д.).",
  "alimony_faq_q4": "Что делать при неуплате?",
  "alimony_faq_a4": "Обратитесь к судебным приставам. Меры: арест счетов, запрет выезда, лишение прав. Задолженность взыскивается за последние 3 года.",
  "alimony_tip_1": "Храните все чеки и подтверждения расходов на ребенка",
  "alimony_tip_2": "При неуплате 3+ месяца - сразу к приставам",
  "alimony_tip_3": "Алименты можно взыскать с бабушек/дедушек если родитель не платит",
