  "money_transfer_receive": "Получатель получит",
  "money_transfer_guide_title": "Как выбрать систему денежных переводов",
  "money_transfer_guide_subtitle1": "Что влияет на стоимость перевода",
  "money_transfer_guide_text1": "Итоговая стоимость перевода складывается из трех компонентов: комиссия системы (1-3% от суммы), наценка на курс обмена валют (1-3%) и дополнительные сборы. Используйте наш калькулятор для сравнения всех систем одновременно.",
  "money_transfer_guide_subtitle2": "Популярные системы переводов в КР",
  "money_transfer_guide_text2": "Koronapay — самая популярная система с широкой сетью точек выдачи. Golden Crown и Contact — надежные системы с большими лимитами. Unistream — быстрые переводы. Western Union и MoneyGram — международные системы для переводов из дальних стран.",
  "money_transfer_guide_subtitle3": "Советы по экономии на переводах",
  "money_transfer_guide_text3": "Сравнивайте не только комиссию, но и курс обмена — часто там скрыта основная разница. Для крупных сумм выбирайте системы с низкой процентной ставкой. Проверьте акции и промокоды систем переводов. Переводы на банковскую карту обычно дешевле, чем выдача наличными.",
  "mobile_tariffs_title": "Калькулятор мобильных тарифов",
  "mobile_tariffs_description": "Сравнение тарифов MegaCom, Beeline, O! в Кыргызстане. Подберите оптимальный тариф по вашему использованию минут, СМС и интернета.",
