  "mobile_tariffs_guide_title": "Как выбрать мобильный тариф",
  "mobile_tariffs_guide_subtitle1": "Оцените свое потребление",
  "mobile_tariffs_guide_text1": "Проверьте статистику использования в приложении оператора за последние 3 месяца. Смотрите средний расход минут, СМС и интернета. Добавьте 20-30% запаса, чтобы не платить за превышение. Если звоните мало — выбирайте тарифы с акцентом на интернет.",
  "mobile_tariffs_guide_subtitle2": "Сравнение операторов Кыргызстана",
  "mobile_tariffs_guide_text2": "MegaCom — крупнейший оператор с лучшим покрытием (98%), оптимален для регионов. Beeline — сильный 4G+ в городах, выгодные семейные пакеты. O! — молодой оператор с агрессивными ценами, хорош для студентов и молодежи. Все операторы предлагают безлимит на соцсети.",
  "mobile_tariffs_guide_subtitle3": "Советы по экономии",
  "mobile_tariffs_guide_text3": "Безлимит не всегда выгоден — рассчитайте свой расход. Следите за акциями операторов, особенно в праздники. Семейные тарифы дают скидку 15-20%. Подключайте автопродление тарифа для бонусов. Используйте Wi-Fi дома и на работе для экономии мобильного интернета. Отключите фоновое обновление приложений.",
  "crop_calc_title": "Калькулятор урожайности для фермеров Кыргызстана",
  "crop_calc_subtitle": "Рассчитайте расходы, доходы и рентабельность выращивания сельскохозяйственных культур",
  "crop_calc_description": "Онлайн калькулятор урожайности и рентабельности для фермеров КР. Расчёт расходов на семена, удобрения, технику и прогноз прибыли. Пшеница, картофель, овощи — все культуры Кыргызстана.",
  "crop_keywords": "калькулятор урожайности, урожай Кыргызстана, рентабельность выращивания культур, расходы на посев, доход фермеров КР",
