  "crop_tip_5": "Учитывайте расходы на полив в засушливых районах",
  "crop_faq_q1": "Как повысить урожайность?",
  "crop_faq_a1": "Используйте качественные семена и удобрения, соблюдайте агротехнику, своевременно поливайте и защищайте от вредителей.",
  "crop_faq_q2": "Какие культуры наиболее выгодны в Кыргызстане?",
  "crop_faq_a2": "Овощи (помидоры, перец, огурцы) дают высокую рентабельность, но требуют больше труда и инвестиций. Зерновые менее прибыльны, но стабильнее.",
  "crop_faq_q3": "Нужно ли использовать удобрения?",
  "crop_faq_a3": "Да, удобрения очень важны для хорошего урожая. Без удобрений урожайность падает на 30-40%. Качественные удобрения окупаются за счёт увеличения урожая.",
  "crop_faq_q4": "Как рассчитать рентабельность?",
  "crop_faq_a4": "ROI = (Доход - Расходы) / Расходы × 100%. Для растениеводства в КР рентабельность 30-50% считается хорошей.",
  "crop_faq_q5": "Где узнать актуальные цены на сельхозпродукцию?",
  "crop_faq_a5": "Следите за ценами на базарах, у агроассоциаций или на сайте Статкомитета КР. Цены сильно зависят от сезона.",
  "rent_calc_title": "Калькулятор аренды жилья в Бишкеке",
