  "rent_tip_1": "Проверяйте документы собственника перед подписанием договора",
  "rent_tip_2": "Фиксируйте состояние квартиры при заселении (фото/видео)",
  "rent_tip_3": "Торгуйтесь — часто цену можно снизить на 10-15%",
