  "rent_tip_5": "Зимой коммунальные платежи выше на 50-70%",
  "rent_faq_q1": "Сколько стоит аренда квартиры в Бишкеке?",
  "rent_faq_a1": "Студия 13,000-25,000 сом, 1-комн. 17,000-30,000 сом, 2-комн. 26,000-45,000 сом, 3-комн. 38,000-65,000 сом. Цены зависят от района и состояния.",
  "rent_faq_q2": "Что такое залог и сколько он составляет?",
  "rent_faq_a2": "Залог — это страховой депозит, обычно равен 2 месяцам аренды. Возвращается при выезде, если нет повреждений.",
  "rent_faq_q3": "Нужно ли платить агентству комиссию?",
  "rent_faq_a3": "Да, обычно 50% от месячной аренды (10,000-30,000 сом). Можно найти без агентства на lalafo.kg, diesel.kg.",
  "rent_faq_q4": "Что выгоднее — аренда или ипотека?",
  "rent_faq_a4": "Зависит от цен. При средних ценах ипотека выгоднее в долгосрочной перспективе, но требует большой первоначальный взнос. Аренда более гибкая.",
  "rent_faq_q5": "Входят ли коммунальные в стоимость аренды?",
  "rent_faq_a5": "Обычно нет. Коммунальные платежи (электричество, вода, отопление) оплачиваются отдельно — 3,000-8,000 сом/мес.",
