  "fuel_yearly_expenses": "Годовые расходы",
  "fuel_current_prices": "Актуальные цены на топливо в Бишкеке (13.03.2026)",
  "fuel_price_note": "Цены актуальны на 13.03.2026 для Бишкека; в регионах возможны отклонения на 2-5 сом и выше по газу.",
  "fuel_tips_title": "Как экономить топливо",
  "fuel_tip_1": "Плавно разгоняйтесь и тормозите — экономия до 20%",
  "fuel_tip_2": "Следите за давлением в шинах — недокачка +10% расхода",
  "fuel_tip_3": "Убирайте лишний груз — каждые 50 кг +2% расхода",
  "fuel_tip_4": "Закрывайте окна на трассе — открытые +5% расхода",
  "fuel_tip_5": "Вовремя делайте ТО — забитый фильтр +15% расхода",
  "fuel_tip_6": "Переходите на газ — в 2 раза дешевле бензина",
  "fuel_faq_q1": "Сколько стоит бензин в Кыргызстане?",
  "fuel_faq_a1": "АИ-92 — 62 сом/л, АИ-95 — 68 сом/л, дизель — 58 сом/л, газ — 28 сом/л (на январь 2026).",
  "fuel_faq_q2": "Выгодно ли переходить на газ?",
  "fuel_faq_a2": "Да! Газ в 2 раза дешевле бензина. Установка ГБО стоит 30,000-50,000 сом и окупается за 10,000-20,000 км.",
  "fuel_faq_q3": "Как рассчитать расход топлива?",
  "fuel_faq_a3": "Формула: (Литры / Километры) × 100. Например, проехали 500 км и потратили 40 литров: (40 / 500) × 100 = 8 л/100км.",
  "fuel_faq_q4": "Где дешевле заправляться в Бишкеке?",
  "fuel_faq_a4": "Цены примерно одинаковые на крупных сетях (Газпромнефть, Tattuu, BP). Дешевле на независимых АЗС, но качество может быть хуже.",
  "fuel_faq_q5": "Сколько стоит съездить из Бишкека в Ош?",
  "fuel_faq_a5": "Расстояние 680 км. Для седана (расход 8.5 л/100км на АИ-95): нужно 58 литров, стоимость ~3,944 сом в одну сторону.",
  "fuel_faq_q6": "Какой расход топлива считается нормальным?",
  "fuel_faq_a6": "Обычно: малолитражки 6-7 л/100км, седаны 8-10, SUV 12-15. Реальный расход зависит от стиля езды, загрузки, погоды и состояния авто.",
  "fuel_faq_q7": "Почему вырос расход топлива?",
  "fuel_faq_a7": "Частые причины: низкое давление в шинах, перегруз, агрессивная езда, забитый фильтр, старые свечи или проблемы с форсунками.",
  "fuel_faq_q8": "Как точнее измерить расход?",
  "fuel_faq_a8": "Заправьте полный бак, обнулите одометр, проедьте 200-300 км и снова заправьте до полного. Расход = (литры / километры) × 100.",
