  "fuel_gas_vs_conclusion_text": "Установка ГБО окупается за 10,000-20,000 км пробега (примерно за 1-2 года для активных водителей).",
  "fuel_saving_tip_1": "Плавный разгон и торможение — резкие старты и остановки увеличивают расход на 20-30%.",
  "fuel_saving_tip_2": "Следите за давлением в шинах — недокачанные шины на 0.5 атм увеличивают расход на 5-10%.",
  "fuel_saving_tip_3": "Убирайте лишний груз — каждые 50 кг лишнего веса +2% к расходу.",
  "fuel_saving_tip_4": "Закрывайте окна на скорости — открытые окна увеличивают аэродинамическое сопротивление (+5% расхода).",
  "fuel_saving_tip_5": "Регулярное ТО — забитый воздушный фильтр +10-15% расхода, старые свечи +5-10%.",
  "fuel_saving_tip_6": "Используйте круиз-контроль — постоянная скорость экономит до 10%.",
