  "construction_faq_q1": "Сколько кирпича нужно на стену?",
  "construction_faq_a1": "В полкирпича (12см) — 51 шт/м², в кирпич (25см) — 102 шт/м², в полтора кирпича (38см) — 153 шт/м². Добавьте 10% на бой.",
