  "electricity_article_faq_title": "FAQ",
  "electricity_article_tariff_population_title": "🏠 Население",
  "electricity_article_tariff_population_item_1": "До 700 кВт·ч: 0.77 сом/кВт·ч",
  "electricity_article_tariff_population_item_2": "Свыше 700 кВт·ч: 2.16 сом/кВт·ч",
  "electricity_article_tariff_highland_title": "⛰️ Высокогорье (льготный)",
  "electricity_article_tariff_highland_item_1": "До 1000 кВт·ч: 0.77 сом/кВт·ч",
