  "water_faq_q1": "Сколько стоит вода в Бишкеке?",
  "water_faq_a1": "С счётчиком — 12-15 сом/м³. Без счётчика — фиксированный тариф ~200-400 сом/мес. Установка счётчика окупается за 3-6 месяцев.",
  "water_faq_q2": "Сколько воды расходует семья?",
  "water_faq_a2": "1 человек — 3-5 м³/мес (150-200 литров/день). Семья из 4 человек — 12-20 м³/мес. Зависит от привычек и наличия стиральной машины.",
  "water_faq_q3": "Как экономить воду?",
  "water_faq_a3": "Закрывайте краны, чините протечки, душ вместо ванны, стиральная машина с полной загрузкой, счётчик. Экономия до 40%.",
  "deposit_faq_q1": "Какая процентная ставка по депозитам в Кыргызстане?",
  "deposit_faq_a1": "В сомах: 10-14% годовых. В долларах: 3-6%. Зависит от суммы (от 10,000 сом) и срока (3 мес - 3 года). Ставки меняются каждый месяц.",
  "deposit_faq_q2": "Застрахованы ли депозиты в КР?",
  "deposit_faq_a2": "Да, до 200,000 сом (с 2026 года). Если банк обанкротится — ФОЗЗ вернёт вклад до этой суммы. Сверх 200,000 сом — риск потери.",
  "deposit_faq_q3": "Что выгоднее — депозит или инвестиции?",
  "deposit_faq_a3": "Депозит — безопасно, но доход низкий (10-14%). Инвестиции (акции, недвижимость) — выше доход, но выше риски. Для краткосрочных целей — депозит.",
  "vehicle_tax_faq_q1": "Сколько транспортный налог в Кыргызстане в 2026?",
  "vehicle_tax_faq_a1": "Зависит от объёма двигателя. До 1.5л — 800 сом/год. 1.5-2.0л — 1,200 сом/год. 2.0-2.5л — 1,800 сом/год. Свыше 2.5л — 3,000+ сом/год.",
  "vehicle_tax_faq_q2": "Когда нужно платить транспортный налог?",
  "vehicle_tax_faq_a2": "До 1 октября каждого года. Квитанцию получите на портале salyk.kg или в налоговой. За просрочку — пеня 10% + 0.1% в день.",
  "vehicle_tax_faq_q3": "Кто освобождён от транспортного налога?",
  "vehicle_tax_faq_a3": "Инвалиды 1-2 группы, ветераны ВОВ, Герои КР, многодетные семьи (на 1 авто). Электромобили освобождены до 2030 года.",
  "sick_calc_title": "Калькулятор больничного листа",
