  "sick_example_3_result_val": "6,212 сом",
  "sick_faq_q1": "Кто оплачивает больничный лист в Кыргызстане?",
  "sick_faq_a1": "Больничный оплачивает работодатель из средств Социального фонда КР. Работодатель делает начисление, а потом получает компенсацию из Соцфонда. Это значит, что если работодатель не делал отчисления в Соцфонд — больничный не оплатят.",
  "sick_faq_q2": "Облагается ли больничный лист налогом?",
  "sick_faq_a2": "Да, больничные облагаются подоходным налогом 10%. Из начисленной суммы вычтут 10%, и вы получите на руки 90%. Это обязательное требование Налогового кодекса КР.",
  "sick_faq_q3": "Можно ли получить больничный, если работаешь неофициально?",
  "sick_faq_a3": "Нет. Если вы работаете без оформления («в конверте»), работодатель не делает отчисления в Социальный фонд. Без отчислений больничный не оплачивается. Это одна из причин, почему важно работать официально.",
  "sick_faq_q4": "Сколько дней больничного можно взять?",
  "sick_faq_a4": "По болезни — до 30 дней (может быть продлён врачебной комиссией), по травме — до 60 дней, по уходу за ребёнком — до 14 дней, по беременности — 126-180 дней.",
  "sick_faq_a4_intro": "Зависит от вида больничного:",
  "sick_faq_a4_illness": "По болезни:",
