  "sick_faq_q5": "Что если заработок меньше МРОТ?",
  "sick_faq_a5": "Если ваша средняя зарплата за 2 года меньше минимального размера оплаты труда (МРОТ = 2,500 сом), больничный рассчитывается исходя из МРОТ. То есть не может быть меньше минимума.",
