  "scholarship_faq_q1": "Когда выплачивается стипендия?",
  "scholarship_faq_a1": "Стипендия выплачивается ежемесячно, обычно 15-20 числа. Первая стипендия — после первой сессии (с декабря для осеннего набора).",
  "scholarship_faq_q2": "Можно ли получать две стипендии одновременно?",
  "scholarship_faq_a2": "Нет. Если вы получаете президентскую стипендию, то академическая не выплачивается. Социальная стипендия может выплачиваться дополнительно к академической.",
  "scholarship_faq_q3": "Что если средний балл упал ниже 3.0?",
  "scholarship_faq_a3": "Стипендия приостанавливается до следующей сессии. Если на следующей сессии GPA поднимется выше 3.0 — выплаты возобновятся.",
  "scholarship_faq_q4": "Кто может получить социальную стипендию?",
  "scholarship_faq_a4": "Социальная стипендия назначается студентам из уязвимых категорий: сиротам, студентам с инвалидностью и студентам из малообеспеченных семей при наличии подтверждающих документов.",
  "scholarship_faq_q5": "Когда выплачивают стипендию?",
  "scholarship_faq_a5": "Обычно стипендия перечисляется ежемесячно в середине месяца. Точные даты зависят от вуза и графика финансирования.",
