  "loan_article_what_title": "Что такое потребительский кредит?",
  "loan_article_what_intro": "Потребительский кредит — это заём в банке для покупки товаров или услуг (без залога или под залог недвижимости/авто). Самый распространённый вид кредита в Кыргызстане.",
