  "loan_article_formula_title": "Формула расчёта аннуитетного платежа",
  "loan_formula_intro": "Большинство банков КР используют аннуитетную схему (равные платежи каждый месяц):",
  "loan_formula_annuity": "Платеж = Сумма × (Ставка/12) × (1 + Ставка/12)^Месяцы / ((1 + Ставка/12)^Месяцы - 1)",
  "loan_formula_explanation": "В первые годы основная часть платежа — проценты, к концу — погашение основного долга.",
  "loan_article_examples_title": "Примеры расчётов",
