  "passport_docs_internal_1": "Свидетельство о рождении (для первичного получения)",
  "passport_docs_internal_2": "Старый паспорт (для замены)",
  "passport_docs_internal_3": "Фото 3×4 (2 шт)",
  "passport_docs_foreign_title": "Для загранпаспорта:",
  "passport_docs_foreign_1": "Паспорт гражданина КР",
  "passport_docs_foreign_2": "Фото 3×4 (2 шт)",
  "passport_docs_foreign_3": "Свидетельство о рождении (для детей)",
  "passport_docs_foreign_4": "Военный билет (для мужчин 18-50 лет)",
  "passport_article_procedure_title": "Порядок оформления",
  "passport_proc_step_1": "Подайте заявление через МФЦ, ГУВД или онлайн (pasp.gov.kg для загранпаспорта)",
  "passport_proc_step_2": "Оплатите госпошлину и сфотографируйтесь (в МФЦ есть фотоуслуги)",
  "passport_proc_step_3": "Ожидайте готовности: обычный срок 30 дней, срочный — 10 дней",
  "passport_proc_step_4": "Получите паспорт при предъявлении квитанции и старого документа",
  "passport_faq_q4": "Когда нужно менять внутренний паспорт?",
  "passport_faq_a4": "Плановая замена в 25 и 45 лет. Также при смене фамилии, порче/утере документа. Штраф за просрочку: 500 сом.",
  "passport_faq_q5": "Что делать при утере паспорта?",
  "passport_faq_a5": "Обратитесь в ГУВД с заявлением об утере. Оформление дубликата: 500 сом (внутренний), 3,000 сом (заграничный). Срок: 30 дней.",
  "passport_sources_label": "Источники: ГУВД КР, МФЦ, актуально на январь 2026",
  "passport_updated": "Обновлено: 23 марта 2026",
  "calorie_article_what_title": "Что такое калории и зачем их считать?",
