  "wedding_article_breakdown_title": "Структура расходов",
  "wedding_breakdown_intro": "Распределение бюджета типичной свадьбы:",
  "wedding_expense_venue": "Ресторан (меню, зал, музыка)",
  "wedding_expense_venue_percent": "40% (120,000-240,000 сом)",
