  "wedding_expense_cars_percent": "15% (45,000-90,000 сом)",
  "wedding_expense_outfits": "Наряды (платье, костюм)",
  "wedding_expense_outfits_percent": "10% (30,000-60,000 сом)",
  "wedding_expense_photo": "Фото/видеосъёмка",
  "wedding_expense_photo_percent": "10% (30,000-60,000 сом)",
  "wedding_expense_other": "Прочее (торт, декор, приглашения)",
  "wedding_expense_other_percent": "25% (75,000-150,000 сом)",
  "wedding_article_saving_title": "Как сэкономить на свадьбе?",
  "wedding_saving_intro": "Реальные способы снизить расходы без ущерба празднику:",
  "wedding_saving_tip_1": "Будни дешевле выходных на 20-30% (рестораны делают скидки)",
  "wedding_saving_tip_2": "Осень/весна дешевле лета (несезон для свадеб)",
  "wedding_saving_tip_3": "Сократите список гостей (каждый гость = 2,000-3,000 сом)",
  "wedding_saving_tip_4": "DIY декор своими руками (экономия 10,000-30,000 сом)",
  "wedding_saving_tip_5": "Молодой фотограф дешевле известного на 30-50%",
  "wedding_article_examples_title": "Примеры бюджетов",
  "wedding_example_1_title": "Скромная свадьба (80 гостей, будний день)",
  "wedding_example_1_desc": "Ресторан: 1,800 сом/чел = 144,000 сом. Кортеж: 20,000 сом. Наряды: 25,000 сом. Фото: 15,000 сом. Итого: ~230,000 сом.",
  "wedding_example_2_title": "Средняя свадьба (150 гостей, выходной)",
  "wedding_example_2_desc": "Ресторан: 2,500 сом/чел = 375,000 сом. Кортеж: 50,000 сом. Наряды: 60,000 сом. Фото/видео: 40,000 сом. Итого: ~550,000 сом.",
  "wedding_faq_q1": "Сколько стоит аренда ресторана в Бишкеке?",
  "wedding_faq_a1": "Цены: 1,500-3,000 сом/человек (включая меню, зал, музыку). Популярные: Достук, Ак-Керемет, City, Europa. Бронируйте за 3-6 месяцев!",
  "wedding_faq_q2": "Как сэкономить на свадьбе?",
  "wedding_faq_a2": "1) Будни дешевле выходных на 20-30%, 2) Осень/весна дешевле лета, 3) Сократите гостей (каждый гость = 2,000-3,000 сом), 4) DIY декор, 5) Фотограф-новичок дешевле.",
  "wedding_faq_q3": "Нужно ли кормить гостей 2 раза?",
  "wedding_faq_a3": "Традиция — да (обед и ужин). Но можно сэкономить, сделав один большой приём. Обсудите с рестораном варианты.",
  "wedding_faq_q4": "Можно ли сделать свадьбу дешевле 200,000 сом?",
  "wedding_faq_a4": "Да! Камерная свадьба на 30-50 человек в кафе (1,200 сом/чел) + минимальный декор + фотограф-знакомый = 100,000-150,000 сом.",
  "wedding_faq_q5": "Сколько дают на свадьбе в конвертах?",
  "wedding_faq_a5": "Средний конверт: 1,000-3,000 сом (зависит от близости отношений). Близкие родственники: 5,000-10,000 сом. Коллеги: 500-1,000 сом. В сумме гости обычно \"отбивают\" 50-70% расходов.",
  "wedding_sources_label": "Источники: цены ресторанов Бишкека, опрос молодожёнов, актуально на январь 2026",
  "wedding_updated": "Обновлено: 23 марта 2026",
  "touristfee_article_what_title": "Туристический сбор в Кыргызстане",
  "touristfee_article_what_intro": "Туристический сбор — местный налог, который туристы платят при проживании в отелях, гостевых домах, санаториях. Собирается при заселении.",
  "touristfee_article_legal_basis": "Основание: Закон КР \"О туризме\", местные решения (Иссык-Кульская, Чуйская области).",
