  "touristfee_exemption_3": "Инвалиды I и II группы",
  "touristfee_exemption_4": "Участники ВОВ и приравненные к ним",
  "touristfee_article_procedure_title": "Порядок оплаты",
  "touristfee_proc_step_1": "При заселении отель/гостевой дом попросит паспорт и рассчитает сумму сбора (дни × ставка × кол-во человек)",
  "touristfee_proc_step_2": "Оплатите сбор наличными или картой (некоторые отели включают в счёт)",
  "touristfee_proc_step_3": "Получите квитанцию об оплате (сохраните на случай проверки)",
  "touristfee_faq_q1": "Обязательно ли платить турсбор?",
  "touristfee_faq_a1": "Да, это обязательный местный налог. Отель/гостевой дом обязан собрать сбор при заселении. Квитанция выдаётся на руки.",
  "touristfee_faq_q2": "Платят ли граждане КР?",
  "touristfee_faq_a2": "Да, турсбор платят все туристы, включая граждан КР. Освобождены только жители данного региона (по прописке).",
  "touristfee_faq_q3": "Что если отель не выдал квитанцию?",
  "touristfee_faq_a3": "Требуйте квитанцию! Без неё вы не защищены. Если отель отказывается — жалоба в налоговую или туристическую инспекцию.",
  "touristfee_faq_q4": "Платится ли турсбор при бронировании через Booking?",
  "touristfee_faq_a4": "Да, турсбор обычно не включён в цену на Booking. Оплачивается на месте при заселении. Уточняйте заранее у отеля.",
  "touristfee_faq_q5": "Можно ли вернуть турсбор?",
  "touristfee_faq_a5": "Нет, турсбор не возвращается даже при досрочном выезде. Это местный налог, который идёт в бюджет региона.",
  "touristfee_sources_label": "Источники: Закон КР \"О туризме\", местные решения, актуально на январь 2026",
  "touristfee_updated": "Обновлено: 23 марта 2026",
  "currency_article_what_title": "Обмен валюты в Кыргызстане",
