  "moneytransfer_article_what_title": "Денежные переводы в Кыргызстан",
  "moneytransfer_article_what_intro": "Система денежных переводов позволяет отправить деньги из-за рубежа или внутри КР за 10-30 минут. Популярные: KoronaPay, Golden Crown, Contact, Western Union.",
  "moneytransfer_article_comparison_note": "Наш калькулятор сравнивает комиссии и курсы разных систем, чтобы вы выбрали самый выгодный вариант.",
  "moneytransfer_systems_title": "Основные системы переводов:",
  "moneytransfer_koronapay": "KoronaPay",
  "moneytransfer_koronapay_desc": "Лидер рынка в КР. Широкая сеть точек, быстро (10-30 мин), комиссия 1.5-3%.",
  "moneytransfer_golden_crown": "Golden Crown (Золотая Корона)",
  "moneytransfer_golden_crown_desc": "Крупная сеть, выдача в банках. Комиссия 2-3%, лимиты до 15,000 USD.",
  "moneytransfer_rates_note": "Курс обмена и комиссии меняются в течение дня — уточняйте на сайтах систем.",
  "moneytransfer_article_comparison_title": "Как выбрать систему перевода?",
  "moneytransfer_comparison_intro": "Сравнивайте по 4 факторам:",
  "moneytransfer_factor_1": "Комиссия — обычно 1.5-3% от суммы (минимум 2-5 USD)",
  "moneytransfer_factor_2": "Курс обмена — системы добавляют наценку 1-3% к курсу НБКР",
  "moneytransfer_factor_3": "Скорость — от 10 минут до 1 часа",
  "moneytransfer_factor_4": "Сеть выдачи — удобство получения в вашем городе",
  "moneytransfer_article_tips_title": "Советы по переводам",
  "moneytransfer_tip_1": "Для крупных сумм (1,000 USD+) сравните 2-3 системы — разница может быть 5-10%",
  "moneytransfer_tip_2": "Курс обычно лучше утром — системы обновляют курсы в начале дня",
  "moneytransfer_tip_3": "При получении наличными проверьте купюры и пересчитайте сумму",
  "moneytransfer_tip_4": "Храните квитанцию до получения перевода (код контроля нужен для выдачи)",
  "moneytransfer_faq_q3": "Можно ли отменить перевод?",
  "moneytransfer_faq_a3": "Да, до момента получения. Обратитесь в ту же точку, где отправляли, с паспортом и квитанцией. Комиссия не возвращается.",
  "moneytransfer_faq_q4": "Что делать, если перевод не пришёл?",
  "moneytransfer_faq_a4": "Проверьте статус на сайте системы по номеру перевода. Если статус \"доступен\" — идите в точку выдачи. Если \"в обработке\" — ждите до 1 часа. Если проблема — звоните в поддержку системы.",
  "moneytransfer_sources_label": "Источники: KoronaPay, Golden Crown, Contact, актуальные тарифы на январь 2026",
  "moneytransfer_updated": "Обновлено: 23 марта 2026",
