  "gas_maintenance_title": "Техобслуживание",
  "gas_maintenance_text": "Ежегодная проверка газового оборудования обязательна. Стоимость проверки — от 500 до 1,500 сом. Вызов аварийной газовой службы — бесплатно по номеру 104.",
  "gas_faq_q5": "Как узнать задолженность по газу?",
