  "pension_check_important_label": "Важно",
  "pension_check_important_text": "Если обнаружите, что работодатель не перечислял взносы, обратитесь в Государственную инспекцию труда (тел. 151) или в Соцфонд для принудительного взыскания задолженности.",

  "pension_faq_q6": "Учитывается ли стаж работы за границей?",
  "pension_faq_a6": "Стаж работы в странах СНГ (Россия, Казахстан и др.) учитывается при расчёте пенсии в Кыргызстане на основании двусторонних соглашений. Для подтверждения необходимо предоставить справку о стаже из пенсионного фонда соответствующей страны. Стаж в странах дальнего зарубежья, как правило, не учитывается, если нет специального соглашения.",
  "pension_faq_q7": "Можно ли работать и получать пенсию одновременно?",
  "pension_faq_a7": "Да, в Кыргызстане работающие пенсионеры получают пенсию в полном размере. При этом работодатель продолжает перечислять взносы в Соцфонд, что может увеличить размер пенсии при перерасчёте. Перерасчёт производится по заявлению пенсионера через каждые 12 месяцев работы после назначения пенсии.",
