  "singletax_faq_q6": "Можно ли совмещать единый налог с другими режимами?",
  "singletax_faq_a6": "Нет, единый налог — это самостоятельный налоговый режим, который заменяет подоходный налог, налог с продаж и НДС. Совмещение с другими режимами не допускается. Однако обязательные отчисления в Социальный фонд уплачиваются отдельно и не входят в единый налог.",
